declare const brand: unique symbol;
type Money = Readonly<{ minor: bigint; currency: Currency; [brand]: "Money" }>;

const money = (minor: bigint, currency: Currency): Money =>
  ({ minor, currency }) as Money;               // validating factory lives here

const add = (a: Money, b: Money): Money => {
  if (a.currency !== b.currency) throw new Error("currency mismatch");
  return money(a.minor + b.minor, a.currency);
};

const total = lines.reduce((acc, l) => add(acc, l.price), money(0n, "EUR"));
